  const payload = JSON.stringify({
    id: batch.id,
    spp: batch.speciesKey,
    mth: batch.methodKey,
    bio: batch.biomassGrams,
    yld: batch.yieldGrams,
    cost: batch.totalCost,
    date: batch.timestamp
  });
