      const dim = n + q * 2;
      let rects = "";
      for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
          if (m[r][c]) rects += '<rect x="' + (c + q) + '" y="' + (r + q) + '" width="1" height="1"/>';
        }
      }
